    ar: 'عرض شامل - الرموز الشريطية و QR',
    fontSize: 16,
    top: 15,
    height: 25,
  );

  final sectionFont = PdfTrueTypeFont(config.assets.primaryFont.toList(), 12);
  double y = 50;
  void section(String en, String ar) {
    page.graphics.drawString(
      isRtl ? ar : en,
      sectionFont,
      brush: PdfSolidBrush(PdfColor(100, 100, 100)),
      bounds: Rect.fromLTWH(20, y, pageSize.width - 40, 20),
      format: PdfStringFormat(
        alignment: PdfTextAlignment.center,
        textDirection: isRtl
            ? PdfTextDirection.rightToLeft
            : PdfTextDirection.leftToRight,
      ),
    );
    y += 25;
  }

  section('— 1D Barcodes —', '— الرموز الشريطية 1D —');
  final half = (pageSize.width - 60) / 2;
  final first = GeniusPdfBarcode.ean13(
    config: config,
    data: '5901234123457',
    caption: 'EAN-13',
    style: const GeniusPdfBarcodeStyle.compact(),
  ).draw(page: page, bounds: Rect.fromLTWH(20, y, half, 80));

  GeniusPdfBarcode.code128(
    config: config,
    data: 'GENIUS-2025',
    caption: 'Code 128',
    style: const GeniusPdfBarcodeStyle.compact(),
  ).draw(
    page: page,
    bounds: Rect.fromLTWH((pageSize.width + 20) / 2, y, half, 80),
  );

  y = first.bottom + 15;
  section('— QR Codes —', '— رموز QR —');
  final qrWidth = (pageSize.width - 80) / 3;

  GeniusPdfQRCodeGenerator.url(
    config: config,
    url: 'https://genius.systems',
    caption: 'URL',
    captionAr: 'رابط',
    style: const GeniusPdfQRCodeStyle.compact(),
  ).draw(page: page, bounds: Rect.fromLTWH(20, y, qrWidth, 90));

  GeniusPdfQRCodeGenerator.zatca(
    config: config,
    sellerName: 'شركة الأمل',
    vatNumber: '300123456789003',
    timestamp: DateTime.now(),
    total: 34615,
    vatAmount: 4515,
    style: const GeniusPdfQRCodeStyle.compact(),
  ).draw(
    page: page,
    bounds: Rect.fromLTWH(40 + qrWidth, y, qrWidth, 90),
  );

  GeniusPdfQRCodeGenerator.wifi(
    config: config,
    ssid: 'Office',
    password: 'pass123',
    style: const GeniusPdfQRCodeStyle.compact(),
  ).draw(
    page: page,
    bounds: Rect.fromLTWH(60 + qrWidth * 2, y, qrWidth, 90),
  );
}

/// Generates one Barcode/QR demo PDF on a worker isolate.
Future<Uint8List> generateBarcodeDocumentInBackground({
  required BarcodeBackgroundDocumentKind kind,
  required bool isRtl,
}) async {
  final config = geniusPdfConfig.copyWith(
    textDirection: isRtl ? TextDirection.rtl : TextDirection.ltr,
  );
  final message = <String, Object?>{
    'config': captureExamplePdfConfig(config),
    'kind': kind.name,
    'isRtl': isRtl,
  };

  final transferred = await Isolate.run<TransferableTypedData>(
    () => _barcodeWorker(message),
    debugName: 'barcode-${kind.name}',
  );
  return transferred.materialize().asUint8List();
}
